                                            else
                                            {
                                                <span class="badge bg-info">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            }
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        @* Revoke Confirmation Dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5);">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Confirm Session Revocation</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke this session?</p>
                            <ul>
                                <li><strong>Device:</strong> @_sessionToRevoke.Device</li>
                                <li><strong>Location:</strong> @_sessionToRevoke.Location</li>
                                <li><strong>Last Active:</strong> @_sessionToRevoke.LastActive.ToString("g")</li>
                            </ul>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
                                @if (_revoking)
                                {
                                    <span class="spinner-border spinner-border-sm me-1"></span>
                                }
                                Revoke Session
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private SecuritySettings? _settings;
    private List<ActiveSession> _sessions = [];
    private bool _twoFactorEnabled;

    // Password change
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordIsError;
    private bool _changingPassword;

    // Session revocation
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
        _sessions = _settings.Sessions;
        _loading = false;
    }

    private async Task ChangePasswordAsync()
    {
        _passwordMessage = null;
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordIsError = true;
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "New password and confirmation do not match.";
            _passwordIsError = true;
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordMessage = "Password updated successfully!";
            _passwordIsError = false;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordMessage = $"Error: {ex.Message}";
            _passwordIsError = true;
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        _twoFactorEnabled = (bool)(e.Value ?? false);
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessions.Remove(_sessionToRevoke);
            _sessionToRevoke = null;
        }
        catch
        {
            // Silently handle for now; could add error display
        }
        finally
        {
            _revoking = false;
        }
    }
}
"}

{"path": "/tmp/sv-cb473872fcf0490cb48d7dcb9361859f/Components/Settings/AppearanceSection.razor", "file_text": "@namespace sv_cb473872fcf0490cb48d7dcb9361859f.Components.Settings
@using sv_cb473872fcf0490cb48d7dcb9361859f.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h3>Appearance</h3>

    @if (_loading)
    {
        <div class="text-center p-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                @* Theme *@
                <div class="mb-4">
                    <h5>Theme</h5>
                    <div class="btn-group" role="group">
                        @foreach (var theme in _themes)
                        {
                            <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                        }
                    </div>
                </div>

                @* Font Size *@
                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        @foreach (var size in _fontSizes)
                        {
                            <input type="radio" class="btn-check" name="fontSize" id="@($"fs-{size}")"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="btn btn-outline-secondary" for="@($"fs-{size}")">@size</label>
                        }
                    </div>
                </div>

                @* Language *@
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width:250px;" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>

                @* Compact Mode *@
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>
            </div>

            @* Live Preview *@
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <strong>Preview</strong>
                    </div>
                    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
                        <h6 style="@GetPreviewFontStyle()">Sample Heading</h6>
                        <p style="@GetPreviewFontStyle()" class="@(_compactMode ? "mb-1" : "mb-3")">
                            This is how your content will look with the selected appearance settings.
                        </p>
                        <button class="btn btn-sm btn-primary">Sample Button</button>
                        <div class="mt-2" style="@GetPreviewFontStyle()">
                            <small class="text-muted">Language: @_language</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show mt-3" role="alert">
                @_message
                <button type="button" class="btn-close" @onclick="() => _message = null"></button>
            </div>
        }

        <button class="btn btn-primary mt-3" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
            await SettingsService.SaveAppearanceAsync(settings);
            _message = "Appearance settings saved!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private string GetPreviewClasses()
    {
        return _theme switch
        {
            "Dark" => "bg-dark text-light",
            "Light" => "bg-white text-dark",
            _ => "bg-light text-dark"
        };
    }

    private string GetPreviewStyles()
    {
        var padding = _compactMode ? "padding:0.5rem;" : "padding:1rem;";
        return padding;
    }

    private string GetPreviewFontStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.2rem;",
            _ => "font-size:1rem;"
        };
        return size;
    }
}
"}

